import{_ as i,o as a,c as t,a5 as e}from"./chunks/framework.D_J2JZBr.js";const c=JSON.parse('{"title":"EDA 环境与 Linux","description":"面向上科大学生的课程环境、EDA 集群、LSF 调度、Linux、Tcl、Make 和 Git 安全入门。","frontmatter":{"title":"EDA 环境与 Linux","description":"面向上科大学生的课程环境、EDA 集群、LSF 调度、Linux、Tcl、Make 和 Git 安全入门。"},"headers":[],"relativePath":"tools/development/index.md","filePath":"tools/development/index.md","lastUpdated":1795531638000}'),n={name:"tools/development/index.md"};function l(h,s,d,p,k,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="eda-环境与-linux" tabindex="-1">EDA 环境与 Linux <a class="header-anchor" href="#eda-环境与-linux" aria-label="Permalink to &quot;EDA 环境与 Linux&quot;">​</a></h1><p>上科大往届课程资料中出现过课程服务器、云桌面，以及经申请使用的 EDA 集群。这些环境<strong>不是同一套资源，也不保证工具、许可证和工艺库完全相同</strong>。当前使用资格、开通流程、保存期限与资源限制，应向<strong>学院电子学科平台或课程助教申请和确认</strong>。</p><p>本页只介绍通用方法，不提供接入地址、账号、密码或管理人员联系方式。不要将这类信息补充到公开 Wiki、截图或代码仓库中。</p><h2 id="先确认环境-再开始实验" tabindex="-1">先确认环境，再开始实验 <a class="header-anchor" href="#先确认环境-再开始实验" aria-label="Permalink to &quot;先确认环境，再开始实验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>通常怎样使用</th><th>应提前确认</th></tr></thead><tbody><tr><td>课程服务器 / 云桌面</td><td>按助教提供的入口和实验说明操作</td><td>课程版本、工作目录、存储期限、备份范围与提交方式</td></tr><tr><td>经授权的 EDA 集群</td><td>登录后通过调度器运行计算任务</td><td>队列、核数、内存、交互图形方式、可用工具模块</td></tr><tr><td>自己的电脑</td><td>编辑、Git、文档、开放工具与小规模验证</td><td>商用工具许可及受限数据能否离开学校环境</td></tr></tbody></table><p>迁移课程实验前检查三件事：<strong>工具及版本是否存在、许可证是否覆盖、PDK 与库是否获准且匹配</strong>。不要因为能启动 Virtuoso，就推断 Genus 或 Innovus 也可用；不要自行复制许可证配置或受限工艺资料来补环境。</p><h2 id="linux-先学够用的命令" tabindex="-1">Linux：先学够用的命令 <a class="header-anchor" href="#linux-先学够用的命令" aria-label="Permalink to &quot;Linux：先学够用的命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>安全习惯</th></tr></thead><tbody><tr><td><code>pwd</code>、<code>ls -lah</code>、<code>cd</code></td><td>定位当前目录和文件</td><td>运行脚本前确认目录，不依赖终端打开时的位置</td></tr><tr><td><code>mkdir -p</code>、<code>cp</code>、<code>mv</code></td><td>创建目录、复制、移动</td><td>覆盖前确认目标；备份不是把大数据库无限复制</td></tr><tr><td><code>less</code>、<code>head</code>、<code>tail</code></td><td>阅读日志</td><td>用 <code>tail -f</code> 跟随正在运行的日志，退出查看不会停止作业</td></tr><tr><td><code>grep</code>、<code>find</code></td><td>查文本与文件</td><td>限定搜索目录，避免扫描共享存储和他人目录</td></tr><tr><td><code>du -sh</code>、<code>df -h</code></td><td>查看目录与文件系统空间</td><td>大波形、数据库和中间文件要按平台规则管理</td></tr><tr><td><code>ps</code>、<code>top</code></td><td>查看进程</td><td>集群作业优先用调度命令查询，不随意终止不属于自己的进程</td></tr><tr><td><code>chmod</code></td><td>设置权限</td><td>不用全员可写权限“解决”所有问题，不修改共享库权限</td></tr><tr><td><code>man</code>、<code>命令 --help</code></td><td>查看帮助</td><td>不明白参数时先读文档，尤其是删除与覆盖操作</td></tr></tbody></table><p>Shell 中空格会分隔参数，路径变量通常应加双引号。<code>&gt;</code> 会覆盖输出文件，<code>&gt;&gt;</code> 是追加，<code>2&gt;</code> 重定向标准错误，管道把前一个命令的标准输出交给后一个。不要把“命令没有打印东西”等同于执行成功，应查看退出码和日志。</p><h2 id="模块、远程图形与-x11" tabindex="-1">模块、远程图形与 X11 <a class="header-anchor" href="#模块、远程图形与-x11" aria-label="Permalink to &quot;模块、远程图形与 X11&quot;">​</a></h2><p>集群可能用环境模块（Environment Modules）管理软件版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> avail</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDA_MODULE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p><code>EDA_MODULE</code> 表示你按平台文档在本地设置的模块名，不是统一固定值。避免无目的地把多个版本叠加到同一 Shell；记录实际加载的版本。某个命令不存在时，先检查模块是否加载，不要立即自行安装另一份工具。</p><p>如果平台允许 SSH 图形转发，可按其指南使用 X11：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDA_LOGIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p><code>EDA_LOGIN</code> 是平台私下提供、由你在本地设置的登录目标，<strong>不要将其值提交到仓库</strong>。本地还需要可用的 X Server；<code>-X</code> 不保证作业节点端也已配置图形转发。只有在可信环境且平台明确要求时才考虑可信转发 <code>-Y</code>。连接异常时按平台指南检查，不关闭系统安全设置来绕过问题。</p><h2 id="lsf-大任务必须进队列" tabindex="-1">LSF：大任务必须进队列 <a class="header-anchor" href="#lsf-大任务必须进队列" aria-label="Permalink to &quot;LSF：大任务必须进队列&quot;">​</a></h2><p><strong>登录节点用于编辑、检查环境、提交和查询作业，不用于直接跑大规模仿真、综合、布局布线或签核。</strong> 图形工具也可能消耗大量资源，应按规定申请交互作业后启动。</p><p>以下是 LSF 的通用示例。<code>BATCH_QUEUE</code>、<code>INTERACTIVE_QUEUE</code> 分别表示平台批准的批处理和交互队列名，需按当前指南在本地设置；<code>run.sh</code> 是你的实际作业脚本。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bqueues</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bsub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BATCH_QUEUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -J</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;demo_%J.log&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;demo_%J.err&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bjobs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bsub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Is</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$INTERACTIVE_QUEUE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre></div><p><code>%J</code> 会由 LSF 替换为作业编号。按程序的真实并行度申请核数，并按平台规定申请内存、时限等资源；不要复制与任务不符的高配参数。交互 Shell 如何启动 GUI、是否需要额外 X11 选项，以平台配置为准。有的平台提供 <code>qrsh</code> 等交互封装，只有在平台指南明确支持时才使用。</p><p>拿到作业编号并在本地设置 <code>JOB_ID</code> 后，可查询详情或停止<strong>自己的</strong>作业：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bjobs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$JOB_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bkill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$JOB_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p><code>bkill</code> 是终止操作，不是刷新命令。排队不等于运行失败；先看作业状态和调度原因。提交后保存编号、日志路径和运行参数，断开终端前确认任务由调度器管理；不要在登录节点用后台命令绕过队列。</p><h2 id="tcl-把工具操作写成脚本" tabindex="-1">Tcl：把工具操作写成脚本 <a class="header-anchor" href="#tcl-把工具操作写成脚本" aria-label="Permalink to &quot;Tcl：把工具操作写成脚本&quot;">​</a></h2><p>许多商用 EDA 工具使用 Tcl。先掌握变量、列表、命令替换、条件与循环：</p><div class="language-tcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> project counter</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rtl_files [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> counter.v tb_counter.v]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">puts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Project: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$rtl_files</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    puts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Input: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这是标准 Tcl 的文件列表演示；<code>read_hdl</code>、<code>synthesize</code> 等 EDA 命令属于具体工具接口，不能在不同产品间照搬。应从课程提供的脚本开始，理解每一步输入、约束和报告；不要只复制一段无法解释的命令让流程“跑到最后”。</p><h2 id="makefile-与-git-减少重复-保留证据" tabindex="-1">Makefile 与 Git：减少重复，保留证据 <a class="header-anchor" href="#makefile-与-git-减少重复-保留证据" aria-label="Permalink to &quot;Makefile 与 Git：减少重复，保留证据&quot;">​</a></h2><p>下面的 Makefile 与 <a href="/shanghaitech-ic-wiki-dev.github.io/tools/open-source/">开源工具页</a> 的计数器示例配套，配方行开头必须是 <strong>Tab</strong>：</p><div class="language-makefile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.PHONY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: sim wave</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: sim.vvp</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	vvp sim.vvp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sim.vvp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: counter.v tb_counter.v</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	iverilog -g2012 -s tb_counter -o </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $^</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wave</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: sim</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	gtkwave counter.vcd</span></span></code></pre></div><p>运行 <code>make sim</code> 完成编译与仿真，<code>make wave</code> 追加波形查看。更大的项目再按实际依赖增加综合与报告目标，不把全部操作塞进一个无法增量执行的长命令。</p><p>Git 优先记录 RTL、测试、约束、脚本和允许公开的文档。用 <code>git status</code> 看状态、<code>git diff</code> 看修改、<code>git log</code> 看历史；提交前逐文件确认。波形、工具数据库、大日志、PDK、许可证和凭证不应进入公开仓库。已有受限文件误入历史时，应按平台要求处理泄露，单纯删除当前文件不能清除历史。</p><h2 id="本地编辑、云端运行的边界" tabindex="-1">本地编辑、云端运行的边界 <a class="header-anchor" href="#本地编辑、云端运行的边界" aria-label="Permalink to &quot;本地编辑、云端运行的边界&quot;">​</a></h2><p>可以在本地写代码、在授权环境运行 EDA，但同步前先区分自主源码和受限材料。使用 AI 或外部服务时，不上传 PDK、许可证配置、服务器信息、未公开网表或研究数据，除非已得到明确授权。同步也不应无差别覆盖服务器目录：先查看差异，保留正在运行任务依赖的输入。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li>本地往届资料：《我的 EDA 集群使用指南》《Linux 常用命令速查》《Makefile 学习》《git》与《本地 AI + 云端 Cadence 工作流与 Makefile 入门》；本页只提炼通用操作，未公开任何接入信息。</li><li><a href="https://sist.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上科大信息学院</a>：平台及课程的当前申请方式请通过学院或助教提供的正式渠道确认。</li><li>通用文档：<a href="https://www.gnu.org/software/bash/" target="_blank" rel="noreferrer">GNU Bash</a>、<a href="https://www.gnu.org/software/make/" target="_blank" rel="noreferrer">GNU Make</a>、<a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a>、<a href="https://www.tcl-lang.org/" target="_blank" rel="noreferrer">Tcl</a>、<a href="https://missing.csail.mit.edu/" target="_blank" rel="noreferrer">MIT Missing Semester</a>。</li></ul>`,37)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
